<?php
declare(strict_types=1);

/**
 * install_admin_paid_payouts_dashboard_v004_20261116_042300pm.php
 *
 * VERSION: v004
 * LAST MODIFIED: 11/16/2026 4:23 pm ET
 *
 * PURPOSE:
 * - Upgrade admin_paid_payouts.php to compact table + expandable team editors.
 * - Upgrade helper for signed fee balance, payment transactions, payout transactions, and rollover.
 * - Create mrl_financial_transactions if missing.
 * - Preserve existing Financial/user_teams data, payout engine, fee history, team-year data,
 *   scoring, scheduler, snapshots, and public payout pages.
 *
 * PHP: 7.3 compatible.
 */

date_default_timezone_set('America/New_York');

$root = dirname(__DIR__);
$installerDir = __DIR__;
$pageTarget = $root.'/admin_paid_payouts.php';
$helperTarget = $root.'/admin_paid_payouts_helper.php';
$backupRoot = $root.'/_installer_backups';
$stateFile = __DIR__.'/.install_admin_paid_payouts_dashboard_v004_state.json';

$PAGE_B64 = '';
$HELPER_B64 = '';
$PAGE_SHA = '8ac31d96c94243faa0cf30893e1855a6d737a684248cccf94dbe67d76e90561e';
$HELPER_SHA = '005a4b293acf3818c5e2fc9aa529151492d2aa9a063e08469570bdcef91f7d87';

function iapp_h($v): string { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
function iapp_lint(string $path): array {
    $out = trim((string)@shell_exec('php -l '.escapeshellarg($path).' 2>&1'));
    return [strpos($out, 'No syntax errors detected') !== false, $out];
}
function iapp_atomic(string $path, string $content): void {
    $tmp = $path.'.tmp_'.getmypid().'_'.bin2hex(random_bytes(3));
    if (@file_put_contents($tmp, $content, LOCK_EX) === false) {
        throw new RuntimeException('Could not write temporary file for '.basename($path));
    }
    @chmod($tmp, 0644);
    if (!@rename($tmp, $path)) {
        @unlink($tmp);
        throw new RuntimeException('Could not install '.basename($path));
    }
    @chmod($path, 0644);
}
function iapp_state_load(string $path): array {
    if (!is_file($path)) return [];
    $d = json_decode((string)@file_get_contents($path), true);
    return is_array($d) ? $d : [];
}
function iapp_state_save(string $path, array $state): void {
    @file_put_contents($path, json_encode($state, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES));
}
function iapp_table_exists(PDO $dbo, string $name): bool {
    $s = $dbo->prepare("SHOW TABLES LIKE :n");
    $s->execute([':n' => $name]);
    return (bool)$s->fetchColumn();
}
function iapp_columns(PDO $dbo, string $table): array {
    $out = [];
    try {
        $q = $dbo->query("SHOW COLUMNS FROM `".$table."`");
        foreach ($q as $r) $out[(string)$r['Field']] = true;
    } catch (Throwable $e) {}
    return $out;
}

$page = base64_decode($PAGE_B64, true);
$helper = base64_decode($HELPER_B64, true);

require_once $root.'/config.php';

$checks = [];
$checks[] = ['Installer running from /public_html/_installers', realpath($installerDir) === realpath($root.'/_installers'), $installerDir];
$checks[] = ['Existing admin_paid_payouts.php present', is_file($pageTarget), $pageTarget];
$checks[] = ['Existing admin_paid_payouts_helper.php present', is_file($helperTarget), $helperTarget];
$checks[] = ['race_results/payouts_helper.php present', is_file($root.'/race_results/payouts_helper.php'), $root.'/race_results/payouts_helper.php'];
$checks[] = ['Financial view readable', (bool)$dbo->query("SELECT 1 FROM Financial LIMIT 1"), 'Financial'];
$checks[] = ['Embedded page decoded', is_string($page), is_string($page) ? strlen($page).' bytes' : 'decode failed'];
$checks[] = ['Embedded helper decoded', is_string($helper), is_string($helper) ? strlen($helper).' bytes' : 'decode failed'];

foreach ([['page', $page], ['helper', $helper]] as $pair) {
    $tmp = tempnam(sys_get_temp_dir(), 'mrl_fin_');
    file_put_contents($tmp, $pair[1]);
    list($ok, $detail) = iapp_lint($tmp);
    @unlink($tmp);
    $checks[] = ['Candidate '.$pair[0].' php -l', $ok, $detail];
}

$preOk = true;
foreach ($checks as $c) {
    if (!$c[1]) $preOk = false;
}

$action = (string)($_POST['action'] ?? '');
$message = '';
$state = iapp_state_load($stateFile);

if ($action === 'apply' && $preOk) {
    try {
        if (!is_dir($backupRoot) && !@mkdir($backupRoot, 0755, true) && !is_dir($backupRoot)) {
            throw new RuntimeException('Could not create backup root.');
        }

        $backupDir = $backupRoot.'/admin_paid_payouts_dashboard_v004_'.date('Ymd_His');

        if (!@mkdir($backupDir, 0755, true) && !is_dir($backupDir)) {
            throw new RuntimeException('Could not create backup folder.');
        }

        foreach ([$pageTarget, $helperTarget] as $target) {
            if (is_file($target) && !@copy($target, $backupDir.'/'.basename($target))) {
                throw new RuntimeException('Could not back up '.basename($target));
            }
        }

        $dbo->exec(
            "CREATE TABLE IF NOT EXISTS mrl_financial_transactions (
                id BIGINT(20) UNSIGNED NOT NULL AUTO_INCREMENT,
                raceYear INT(11) NOT NULL,
                userID INT(11) NOT NULL,
                teamName VARCHAR(255) NOT NULL DEFAULT '',
                transaction_type VARCHAR(32) NOT NULL,
                amount DECIMAL(10,2) NOT NULL DEFAULT 0.00,
                method VARCHAR(100) NOT NULL DEFAULT '',
                source_account VARCHAR(150) NOT NULL DEFAULT '',
                occurred_at DATETIME DEFAULT NULL,
                entered_date_text VARCHAR(120) NOT NULL DEFAULT '',
                note TEXT DEFAULT NULL,
                linked_transaction_id BIGINT(20) UNSIGNED DEFAULT NULL,
                created_by INT(11) NOT NULL DEFAULT 0,
                created_at DATETIME NOT NULL,
                voided_at DATETIME DEFAULT NULL,
                voided_by INT(11) DEFAULT NULL,
                void_reason VARCHAR(255) NOT NULL DEFAULT '',
                PRIMARY KEY (id),
                KEY idx_mrl_fin_txn_year_user (raceYear,userID),
                KEY idx_mrl_fin_txn_type (raceYear,transaction_type),
                KEY idx_mrl_fin_txn_link (linked_transaction_id)
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci"
        );

        iapp_atomic($helperTarget, $helper);
        iapp_atomic($pageTarget, $page);

        foreach ([[$helperTarget, $HELPER_SHA], [$pageTarget, $PAGE_SHA]] as $item) {
            list($lintOk, $lintDetail) = iapp_lint($item[0]);

            if (!$lintOk) {
                throw new RuntimeException('Installed '.basename($item[0]).' failed php -l: '.$lintDetail);
            }

            if (hash_file('sha256', $item[0]) !== $item[1]) {
                throw new RuntimeException('Installed '.basename($item[0]).' SHA mismatch.');
            }
        }

        $state = [
            'applied' => true,
            'applied_at' => date('c'),
            'backup_dir' => $backupDir,
        ];
        iapp_state_save($stateFile, $state);
        $message = 'PASS — v004 dashboard/transaction upgrade installed.';
    } catch (Throwable $e) {
        $message = 'FAIL — '.$e->getMessage();
    }
}

$state = iapp_state_load($stateFile);
$post = [];

if (!empty($state['applied'])) {
    foreach ([[$pageTarget, $PAGE_SHA, 'admin_paid_payouts.php'], [$helperTarget, $HELPER_SHA, 'admin_paid_payouts_helper.php']] as $item) {
        $exists = is_file($item[0]);
        $post[] = [$item[2].' exists', $exists, $item[0]];

        if ($exists) {
            list($lintOk, $lintDetail) = iapp_lint($item[0]);
            $post[] = [$item[2].' php -l', $lintOk, $lintDetail];
            $post[] = [$item[2].' SHA matches', hash_file('sha256', $item[0]) === $item[1], hash_file('sha256', $item[0])];
        }
    }

    $post[] = ['mrl_financial_transactions exists', iapp_table_exists($dbo, 'mrl_financial_transactions'), 'transaction ledger'];

    $cols = iapp_columns($dbo, 'mrl_financial_transactions');
    $need = ['id','raceYear','userID','teamName','transaction_type','amount','method','source_account','occurred_at','entered_date_text','note','linked_transaction_id','created_by','created_at','voided_at','voided_by','void_reason'];
    $missing = [];
    foreach ($need as $n) if (!isset($cols[$n])) $missing[] = $n;
    $post[] = ['transaction schema ready', empty($missing), empty($missing) ? 'all expected columns present' : 'missing: '.implode(', ', $missing)];
}
?>
